// --- Targets (4) ---
//
// Each target carries its Michaelis constant Kₘ for ATP. Values are
// representative literature ranges for the kinase domains; CDK2 / CDK4 /
// CDK6 ATP Kₘ ≈ 15–30 μM, EGFR ≈ 3–8 μM. Used in cell 28's loop-closure
// query that ties the Kᵢ fit back to the screened IC₅₀ via Cheng–Prusoff.

resource assay:CDK2 : assay:Target {
    assay:target_name             = "CDK2";
    assay:target_family           = "CDK";
    assay:michaelis_constant_um   = 20.0;
}

resource assay:CDK4 : assay:Target {
    assay:target_name             = "CDK4";
    assay:target_family           = "CDK";
    assay:michaelis_constant_um   = 25.0;
}

resource assay:CDK6 : assay:Target {
    assay:target_name             = "CDK6";
    assay:target_family           = "CDK";
    assay:michaelis_constant_um   = 22.0;
}

resource assay:EGFR : assay:Target {
    assay:target_name             = "EGFR";
    assay:target_family           = "EGFR";
    assay:michaelis_constant_um   = 5.0;
}

// --- Protocols (3) ---
//
// Each protocol carries its [ATP] running concentration. These are
// chosen so Kinase-Glo's [S] = 80 μM combined with CDK2's Kₘ = 20 μM
// yields a Cheng–Prusoff coefficient (1 + [S]/Kₘ) = 5 — making the
// predicted IC₅₀ at the fitted Kᵢ = 17 nM exactly 85 nM, which matches
// the measured EIG_0291 / CDK2 / Kinase-Glo result in cell 4 (R0013).
// The chain ties the Part-B fit back to the Part-A measurement.

resource assay:KinaseGlo : assay:AssayProtocol {
    assay:protocol_name             = "Kinase-Glo";
    assay:incubation_minutes        = 60;
    assay:substrate_concentration_um = 80.0;
}

resource assay:ADPGlo : assay:AssayProtocol {
    assay:protocol_name             = "ADP-Glo";
    assay:incubation_minutes        = 45;
    assay:substrate_concentration_um = 100.0;
}

resource assay:TRFRET : assay:AssayProtocol {
    assay:protocol_name             = "TR-FRET";
    assay:incubation_minutes        = 90;
    assay:substrate_concentration_um = 50.0;
}

