// Selectivity matrix — every QC-passing AssayResult, joined to its
// compound + target. This is the data a Phase 5 grouped-bar chart
// would consume (one bar per (compound, target) IC50; group by
// compound, colour by target).

USING "urn:eigenius:demo:assay:AssayResult"
USING NAMESPACE "urn:eigenius:demo:assay:"

MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":         ?c,
    "urn:eigenius:demo:assay:target":           ?t,
    "urn:eigenius:demo:assay:ic50_nm":          ?ic50,
    "urn:eigenius:demo:assay:ci_low_nm":        ?ci_low,
    "urn:eigenius:demo:assay:ci_high_nm":       ?ci_high,
    "urn:eigenius:demo:assay:replicate_count":  ?n,
    "urn:eigenius:demo:assay:passed_qc":        ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name": ?target_name }
WHERE ?qc = true
RETURN [] {
    compound: ?compound_id,
    target:   ?target_name,
    ic50_nm:  ?ic50,
    ci_low:   ?ci_low,
    ci_high:  ?ci_high,
    n:        ?n
}
ORDER BY ?compound_id

// QC pass-rate by protocol. The chart Phase 5 would render: a donut
// or stacked bar chart showing how many results passed/failed per
// protocol — TR-FRET runs the very-weak EGFR off-target measurements
// and absorbs all the QC failures, while Kinase-Glo / ADP-Glo are
// clean.

USING "urn:eigenius:demo:assay:AssayResult"
USING NAMESPACE "urn:eigenius:demo:assay:"

MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:protocol":   ?p,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?p { "urn:eigenius:demo:assay:protocol_name": ?protocol_name }
RETURN [] {
    protocol: ?protocol_name,
    qc:       ?qc
}
ORDER BY ?protocol_name

cells.query:
// IC50 selectivity profile — grouped bar chart. One group per
// compound; one bar per target within each group; bar height is
// IC50 in nM (lower = more potent). CDK-selective compounds show
// short bars on their preferred target and tall bars on EGFR; the
// EGFR-selective EIG_0203 shows the inverse.

USING "urn:eigenius:demo:assay:AssayResult"
USING NAMESPACE "urn:eigenius:demo:assay:"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":   ?c,
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name": ?target_name }
WHERE ?qc = true
RETURN [] {
    compound: ?compound_id,
    target:   ?target_name,
    ic50_nm:  ?ic50
}
ORDER BY ?compound_id

// QC pass / fail breakdown across all 24 results. Donut showing how
// QC failures concentrate on the very-weak EGFR off-target
// measurements (which all run on the TR-FRET protocol).

USING "urn:eigenius:demo:assay:AssayResult"
USING NAMESPACE "urn:eigenius:demo:assay:"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:passed_qc": ?qc
}
GROUP BY ?qc
RETURN [] {
    status: ?qc,
    count:  COUNT(?r)
}

// Mean IC50 per target across QC-passing measurements. Vertical-bar
// chart — single series, one bar per target. CDK targets cluster at
// low IC50 (most compounds are CDK-active); EGFR averages much
// higher because only EIG_0203 hits it.

USING "urn:eigenius:demo:assay:AssayResult"
USING NAMESPACE "urn:eigenius:demo:assay:"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?t { "urn:eigenius:demo:assay:target_name": ?target_name }
WHERE ?qc = true
GROUP BY ?target_name
RETURN [] {
    target:    ?target_name,
    mean_ic50: AVG(?ic50)
}
ORDER BY ?target_name

// Compounds ranked by molecular weight. Horizontal-bar chart — bar
// labels along the y-axis, bar length is MW in g/mol. Sorted
// descending so the heaviest scaffold (quinazoline) tops the list.

USING "urn:eigenius:demo:assay:Compound"
USING NAMESPACE "urn:eigenius:demo:assay:"
MATCH Compound(?c) {
    "urn:eigenius:demo:assay:compound_id":      ?compound_id,
    "urn:eigenius:demo:assay:molecular_weight": ?mw
}
RETURN [] {
    compound: ?compound_id,
    mw:       ?mw
}
ORDER BY ?mw DESC

// IC50 trajectory across CDK targets, one line per compound. Lines
// that stay flat-and-low (EIG_0291) indicate pan-CDK activity; lines
// with deep notches (EIG_0042 at CDK2, EIG_0117 at CDK4) flag
// selectivity. EGFR is excluded so the CDK story isn't crushed by
// the off-target IC50 scale.

USING "urn:eigenius:demo:assay:AssayResult"
USING NAMESPACE "urn:eigenius:demo:assay:"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":   ?c,
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name":   ?target_name,
     "urn:eigenius:demo:assay:target_family": ?fam }
WHERE ?qc = true AND ?fam = "CDK"
RETURN [] {
    compound: ?compound_id,
    target:   ?target_name,
    ic50_nm:  ?ic50
}
ORDER BY ?compound_id, ?target_name

// Mean IC50 by scaffold class across CDK targets — area chart with
// one series per scaffold (pyrimidine / indazole / quinazoline /
// pyrazolopyrimidine). Reveals which scaffold family is most potent
// on which kinase. Pyrazolopyrimidine (EIG_0291) traces a near-flat
// pan-CDK profile; quinazoline (EIG_0203) sits well above the others
// across all CDKs.

USING "urn:eigenius:demo:assay:AssayResult"
USING NAMESPACE "urn:eigenius:demo:assay:"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":   ?c,
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?c { "urn:eigenius:demo:assay:scaffold_class": ?scaffold },
?t { "urn:eigenius:demo:assay:target_name":   ?target_name,
     "urn:eigenius:demo:assay:target_family": ?fam }
WHERE ?qc = true AND ?fam = "CDK"
GROUP BY ?scaffold, ?target_name
RETURN [] {
    scaffold:  ?scaffold,
    target:    ?target_name,
    mean_ic50: AVG(?ic50)
}
ORDER BY ?scaffold, ?target_name

cells.source:
// Full ontology topology graph for the assay namespace. Fetches the
// layer chain with class / property / institution nodes (no per-
// resource nodes — that'd be 30+ extra dots), filters out everything
// outside the assay namespace, and routes the result to xyflow via
// the auto-renderer.
//
// Each kind gets its own colour: classes blue, properties green,
// institutions purple. Edges are coloured by relationship
// (`is_a` / `subclass_of` / `requires` / `recommends` / `property_ref`).

const topo = await eigen.layerTopology({ includeResources: false });

const PREFIX = "urn:eigenius:demo:assay:";
const keep = new Set();
for (const n of topo.nodes) {
  if (n.id.startsWith(PREFIX)) keep.add(n.id);
}

return {
  nodes: topo.nodes.filter((n) => keep.has(n.id)),
  edges: topo.edges.filter((e) => keep.has(e.source) && keep.has(e.target)),
};

// Catalyst-side primary resource — a typed reaction network. The
// Catalyst → DiffEq comorphism's `compile_to_ode` handler parses the
// `network_source` string, derives the symbolic ODE RHS, translates
// each component into a `formulas:FormulaTerm`, and packs into an
// `OdeProblem`. Cell 17 commits that OdeProblem hand-authored, but
// the structural intent is identical: the comorphism would produce
// the same chain bytes.

namespace core     = "urn:eigenius:core";
namespace catalyst = "urn:eigenius:catalyst";
namespace nb       = "urn:eigenius:notebook:kinase_demo";

resource nb:ab_network : catalyst:ReactionNetwork {
    core:short_name              = "eig0291_cdk2_binding";
    catalyst:network_source      = "@reaction_network begin\n    k, A --> B\nend";
    catalyst:species_declared    = ["A", "B"];
    catalyst:parameters_declared = ["k"];
}

// Hand-author the chain-typed OdeProblem the Catalyst → DiffEq
// comorphism would produce by compiling the network in cell 16.
// `dA/dt = -k·A`, `dB/dt = k·A` — Catalyst's `compile_to_ode` handler
// emits these as App-spines over the operator catalog. Each App
// node binds exactly two children (the chain operator catalog
// declares `mul`, `add`, etc. as binary), so multi-operand
// expressions are *left-folded into nested binary apps*:
//   (-1) · A · k   becomes   `mul(mul(-1, A), k)`.
// The naïve flat shape `App(App(App(OpRef(mul), -1), A), k)` would
// be a 3-arg App-spine — the chain validator would reject it with
// `OperatorArityMismatch` against `mul`'s declared binary arity.
//
// Inductive-value literals (`App(...)`, `OpRef(...)`, `Var(...)`,
// `LitFloat(...)`) are D32 ctor calls — Phase 19f.2 added them to
// the ESL surface so FormulaTerm payloads can be authored typed +
// inline rather than via raw `eigen.load(JSON.stringify(...))` from
// a TypeScript cell. The compiler lowers each call into a chain
// `Value::Json` carrying the canonical `{ctor, args}` tagged-dict
// shape that the kernel's inductive-value validator walks against
// FormulaTerm's ctor schema at commit time.
//
// Committing the OdeSolution fires the DiffEq AutoOnLoad gate:
//   1. Decode the embedded OdeProblem via the generated mirror.
//   2. Walk each FormulaTerm RHS under `formula_to_value` to build
//      a numerical closure.
//   3. Construct an `ODEProblem(rhs!, u0, tspan, p)` and solve via
//      `Tsit5` at abstol = reltol = 1e-8.
//   4. Per-component compare `sol.u[end]` against `final_state`;
//      tolerance bound is `max(abstol, reltol·|actual|)`.
//   5. Verdict: Holds (matches), Fails (mismatch beyond tolerance),
//      Undecidable (solver hit indeterminate state).

namespace core   = "urn:eigenius:core";
namespace diffeq = "urn:eigenius:diffeq";
namespace nb     = "urn:eigenius:notebook:kinase_demo";

// `formula(...)` is the math-style infix sublanguage for inductive
// FormulaTerm values (Phase 19f.3). Standard `+ - * / ^` precedence,
// function calls map directly to the chain operator catalog at
// `urn:eigenius:formulas:ops:<name>`. Each binary App in the
// resulting tree carries exactly the operator's declared arity
// (the parser left-folds n-ary expressions into nested binary
// apps, so `(-1) * A * k` lowers to `mul(mul(-1, A), k)` not the
// 3-arg App-spine the chain validator would reject).
resource nb:rhs_A : diffeq:RhsComponent {
    diffeq:term = formula(-1 * A * k);  // dA/dt = -k·A
}

resource nb:rhs_B : diffeq:RhsComponent {
    diffeq:term = formula(A * k);       // dB/dt = k·A
}

resource nb:ode_problem : diffeq:OdeProblem {
    core:short_name           = "eig0291_cdk2_binding";
    diffeq:state_names        = ["A", "B"];
    diffeq:parameter_names    = ["k"];
    diffeq:rhs                = [nb:rhs_A, nb:rhs_B];
    diffeq:initial_conditions = [1.0, 0.0];
    diffeq:parameters         = [1.0];
    diffeq:time_span_start    = 0.0;
    diffeq:time_span_end      = 1.0;
}

// Closed form at t=1 with k=1, A(0)=1, B(0)=0:
//   A(1) = e^-1 ≈ 0.36787944117144233
//   B(1) = 1 - e^-1 ≈ 0.6321205588285577
resource nb:ode_solution : diffeq:OdeSolution {
    core:short_name    = "eig0291_cdk2_binding_solution";
    diffeq:problem     = nb:ode_problem;
    diffeq:algorithm   = "Tsit5";
    diffeq:abstol      = 0.00000001;
    diffeq:reltol      = 0.00000001;
    diffeq:final_state = [0.36787944117144233, 0.6321205588285577];
}

// Query the Verdict the DiffEq AutoOnLoad gate just produced.
// `verdict_subject` points at the OdeSolution that was gated; we
// filter to it so this view shows only the verdict from cell 17.
//
// `Verdict` is declared as a `core:InductiveType` (the tri-state
// `Holds | Fails | Undecidable` ctor schema), not a `core:Class`,
// so EigenQL's `USING` clause refuses it. Use the bare-IRI MATCH
// form instead — same shape as the diffeq / catalyst demo run.sh
// scripts.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name":               ?ctor,
    "urn:eigenius:institution:verdict_subject":  ?subject
}
WHERE ?subject = "urn:eigenius:notebook:kinase_demo:ode_solution"
RETURN [] {
    verdict:  ?v,
    ctor:     ?ctor,
    subject:  ?subject
}

// Symbolics → JuMP path. Author the SSE objective as a SymbolicExpression
// carrying a FormulaTerm, wrap in the SymbolicsToJuMPInput composite,
// commit the OptimisationProblem the comorphism would produce, and
// commit the OptimisesTo claim that JuMP-HiGHS will re-solve and verify.
//
// SSE = (34 - 2*Ki)^2 + (68 - 4*Ki)^2 + (170 - 10*Ki)^2.  Three
// residuals chained with `add` (left-spined). Each residual is
//   pow(sub(IC50_obs, mul(c, Ki)), 2)
// — straightforward but verbose without let-bindings; D32 ESL v1's
// inline literal form requires the SSE to appear twice (once on the
// SymbolicExpression, once on the OptimisationProblem.objective
// the comorphism would produce).
//
// Coefficients come from EIG_0291 / CDK2 (Kₘ = 20 μM) at the synthetic
// dose-response panel [S] ∈ {20, 60, 180} μM:
//   c = 1 + [S]/Kₘ ∈ {2, 4, 10}
//   IC₅₀_obs = Kᵢ · c with Kᵢ_true = 17 nM → {34, 68, 170}
// SSE expansion: 120·Kᵢ² − 4080·Kᵢ + 34680, minimised at Kᵢ = 17, SSE = 0.

namespace core      = "urn:eigenius:core";
namespace symbolics = "urn:eigenius:symbolics";
namespace jump      = "urn:eigenius:jump";
namespace nb        = "urn:eigenius:notebook:kinase_demo";

resource nb:sse_expr : symbolics:SymbolicExpression {
    core:short_name = "eig0291_cdk2_ki_fit_sse";
    symbolics:term = formula((34 - 2*Ki)^2 + (68 - 4*Ki)^2 + (170 - 10*Ki)^2);
}

resource nb:ki_bound : jump:VariableBound {
    jump:variable_name = "Ki";
    jump:lower         = 0.0;
    jump:upper         = 50.0;
}

// Comorphism input — the `qc_symb_to_jump` OnDemand handler reads
// `objective.term` (identity on FormulaTerm) and forwards the rest
// of the framing fields unchanged into an OptimisationProblem.
resource nb:fit_input : symbolics:SymbolicsToJuMPInput {
    core:short_name                  = "eig0291_cdk2_ki_fit_input";
    symbolics:objective              = nb:sse_expr;
    symbolics:variable_names         = ["Ki"];
    symbolics:framing_variable_bounds = [nb:ki_bound];
    symbolics:sense                  = "Min";
}

// What the comorphism would produce — same SSE FormulaTerm as in
// `nb:sse_expr.term` above. (No let-bindings in ESL yet, so the
// expression is duplicated; both copies parse via the same
// `formula(...)` Pratt path.)
resource nb:opt_problem : jump:OptimisationProblem {
    core:short_name      = "eig0291_cdk2_ki_fit_problem";
    jump:variable_names  = ["Ki"];
    jump:variable_bounds = [nb:ki_bound];
    jump:objective       = formula((34 - 2*Ki)^2 + (68 - 4*Ki)^2 + (170 - 10*Ki)^2);
    jump:sense           = "Min";
}

resource nb:optimises_to : jump:OptimisesTo {
    core:short_name             = "eig0291_cdk2_ki_fit_optimum";
    jump:problem                = nb:opt_problem;
    jump:termination_status     = "OPTIMAL";
    jump:objective_value        = 0.0;
    jump:variable_values        = [17.0];
    jump:abstol                 = 0.000001;
    jump:reltol                 = 0.000001;
}

// Verdict from the JuMP-HiGHS AutoOnLoad gate. The gate rebuilt
// the OptimisationProblem under the FormulaTerm walker (smart-pow
// on, so `pow(•, 2.0)` unrolled to `(• * •)` and HiGHS saw a
// QuadExpr), called `optimize!`, and tolerance-checked the
// resolved objective against the claimed `objective_value = 0.0`.
// Holds means the institution independently reproduced Ki* = 2.0,
// SSE* = 0 within `max(abstol, reltol·|actual|) = 1e-6`.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name":               ?ctor,
    "urn:eigenius:institution:verdict_subject":  ?subject
}
WHERE ?subject = "urn:eigenius:notebook:kinase_demo:optimises_to"
RETURN [] {
    verdict:  ?v,
    ctor:     ?ctor,
    subject:  ?subject
}

// All Verdicts the notebook produced. The two AutoOnLoad gates
// (DiffEq + JuMP-HiGHS) each fired once; this view aggregates both
// rows along with their gated subjects so a quick scan confirms
// every claim landed under its expected institution.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name":                   ?ctor,
    "urn:eigenius:institution:verdict_subject":      ?subject,
    "urn:eigenius:institution:verdict_query_class":  ?qc
}
RETURN [] {
    verdict:     ?v,
    ctor:        ?ctor,
    subject:     ?subject,
    query_class: ?qc
}
ORDER BY ?ctor

// The JuMP-HiGHS gate fired against the OptimisesTo claim, re-solved
// the QP fresh, and confirmed Holds. Pulling the claim's fields
// alongside the Verdict shows the values the institution *endorsed*
// — Kᵢ_fitted = 17.0 nM, SSE_min = 0.0, status = OPTIMAL — to within
// the claimed tolerances (abstol = reltol = 1e-6). The gate's Holds
// turns these from "the author's claim" into "the institution's
// answer up to numerical precision".
//
// Two MATCH clauses joined by a single trailing WHERE: D2 §3.1
// requires WHERE to come once, after all MATCH/FIBER clauses (the
// `match_part ::= ... clause+ where_clause?` production).

USING "urn:eigenius:jump:OptimisesTo"
USING NAMESPACE "urn:eigenius:jump:"

MATCH OptimisesTo(?o) {
    "urn:eigenius:jump:variable_values":     ?vals,
    "urn:eigenius:jump:objective_value":     ?obj,
    "urn:eigenius:jump:termination_status":  ?status,
    "urn:eigenius:jump:abstol":              ?abstol,
    "urn:eigenius:jump:reltol":              ?reltol
}
MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name":              ?ctor,
    "urn:eigenius:institution:verdict_subject": ?o
}
WHERE ?o = "urn:eigenius:notebook:kinase_demo:optimises_to"

RETURN [] {
    fitted_Ki_nM:     ?vals,
    sse_min:          ?obj,
    termination:      ?status,
    tolerance:        ?abstol,
    institution_says: ?ctor
}

// The RuntimeInvocation provenance closure attached to each Verdict
// (D31 §6.3). For each gate firing the chain records: the env image
// digest that executed the dispatch, the start/end timestamps, and
// the BLAS / FMA / GPU determinism metadata captured at worker
// bootstrap (D26 §5.5). This is the closure that makes the
// institution's answer reproducible — a re-run on the same image
// with matching `numerical_metadata` produces identical bytes by
// construction.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name":                  ?ctor,
    "urn:eigenius:institution:verdict_subject":     ?subject,
    "urn:eigenius:institution:runtime_invocation":  ?inv
}

MATCH "urn:eigenius:runtime:RuntimeInvocation"(?inv) {
    "urn:eigenius:runtime:image_digest":       ?digest,
    "urn:eigenius:runtime:started_at":         ?start,
    "urn:eigenius:runtime:completed_at":       ?end,
    "urn:eigenius:runtime:numerical_metadata": ?numerics
}

RETURN [] {
    verdict:        ?v,
    ctor:           ?ctor,
    subject:        ?subject,
    image_digest:   ?digest,
    started_at:     ?start,
    completed_at:   ?end,
    numerical_meta: ?numerics
}
ORDER BY ?subject

// Loop-closure join. Pull the screened EIG_0291 / CDK2 / Kinase-Glo
// row (R0013), the kinetic constants the chain records on the Target
// and Protocol resources, and the fitted Kᵢ from the OptimisesTo —
// then surface them side by side. The reader computes the
// Cheng–Prusoff prediction:
//
//     predicted_IC50 = fitted_Ki * (1 + S_uM / Km_uM)
//                    = 17 * (1 + 80/20) = 17 * 5 = 85 nM
//
// — and compares against `ic50_measured` (85 nM, CI [72, 100]). The
// chain provides every input; the math is one line of arithmetic.
//
// Two MATCH clauses joined by a single trailing WHERE: D2 §3.1
// requires WHERE to come once, after all MATCH/FIBER clauses
// (the `match_part ::= ... clause+ where_clause?` production).

USING "urn:eigenius:demo:assay:AssayResult"
USING NAMESPACE "urn:eigenius:demo:assay:"
USING "urn:eigenius:jump:OptimisesTo"
USING NAMESPACE "urn:eigenius:jump:"

MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":   ?c,
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:protocol":   ?p,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50_measured,
    "urn:eigenius:demo:assay:ci_low_nm":  ?ci_low,
    "urn:eigenius:demo:assay:ci_high_nm": ?ci_high,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name":            ?target_name,
     "urn:eigenius:demo:assay:michaelis_constant_um":  ?Km_uM },
?p { "urn:eigenius:demo:assay:protocol_name":             ?protocol_name,
     "urn:eigenius:demo:assay:substrate_concentration_um": ?S_uM }
MATCH OptimisesTo(?o) {
    "urn:eigenius:jump:variable_values": ?fitted_Ki
}
WHERE ?compound_id = "EIG_0291"
  AND ?target_name = "CDK2"
  AND ?protocol_name = "Kinase-Glo"
  AND ?qc = true
  AND ?o = "urn:eigenius:notebook:kinase_demo:optimises_to"

RETURN [] {
    compound:           ?compound_id,
    target:             ?target_name,
    protocol:           ?protocol_name,
    Km_uM:              ?Km_uM,
    S_uM:               ?S_uM,
    fitted_Ki_nM:       ?fitted_Ki,
    ic50_measured_nM:   ?ic50_measured,
    ic50_ci_low_nM:     ?ci_low,
    ic50_ci_high_nM:    ?ci_high
}

